import subprocess, os, shutil
E="/workspace/executable"
def fresh(tag):
    home=f"/tmp/probe-6/fx-{tag}"
    shutil.rmtree(home, ignore_errors=True); os.makedirs(home)
    return dict(os.environ, HOME=home, XDG_CONFIG_HOME=f"{home}/.config", XDG_DATA_HOME=f"{home}/.data"), home
def listfiles(home):
    out=[]
    for r,d,fs in os.walk(home):
        for f in fs: out.append(os.path.join(r,f).replace(home+"/",""))
    return sorted(out)
for tag,args in [("noargs",[]),("help",["help"]),("claperr",["--bogus"]),("subhelp",["help","vault"]),
                 ("vault_l",["vault","-l"]),("config",["config"]),("runtime_err",["enter","zzz"]),
                 ("v_ok",["vault","a","/tmp/probe-6"])]:
    env,home=fresh(tag)
    p=subprocess.run([E]+args, capture_output=True, env=env, input=b"")
    files=listfiles(home)
    print(f"### {tag:12} exit={p.returncode} files={files}")
    for f in files: print("   ", f, repr(open(os.path.join(home,f),"rb").read()))
# also check what vault creation dropped in /tmp/probe-6 (vault dir)
for r,d,fs in os.walk("/tmp/probe-6/a"):
    for f in fs: print("vaultdir:", os.path.join(r,f), repr(open(os.path.join(r,f),"rb").read()))
EOF
